    fn finish_locked(&self,store:&Store,reference:&DataUseReceiptRef,outcome:DataUseOutcome,results:Vec<ArtifactDigest>)->Result<(),String>{store.mutate(|s|Self::finish_in_snapshot(s,reference,outcome,results))}
