    let cats=[(DataCategory::HumanText,"Texto humano"),(DataCategory::TargetMetadata,"Metadados de alvo"),(DataCategory::ExecutionSummary,"Resumo de execução"),(DataCategory::EvidenceExcerpt,"Trecho de evidência"),(DataCategory::SourceExcerpt,"Trecho de fonte"),(DataCategory::FindingText,"Texto de achado"),(DataCategory::ActivityMetadata,"Atividade")];
