    #[test]fn migration_five_keeps_exact_json_without_automatic_authority(){
        let f=Fixture::new("original");let path=f.store.root.join("openkoda.sqlite3");let old=format!("\n{}\n",serde_json::to_string_pretty(&f.store.snapshot().unwrap()).unwrap());drop(f.service);drop(f.store);let db=rusqlite::Connection::open(&path).unwrap();db.execute("UPDATE app_state SET json=?1 WHERE id=1",[&old]).unwrap();db.pragma_update(None,"user_version",5).unwrap();drop(db);let store=Store::open(path.parent().unwrap().into()).unwrap();assert!(store.snapshot().unwrap().data_policies.is_empty());drop(store);let db=rusqlite::Connection::open(path).unwrap();let actual:String=db.query_row("SELECT json FROM app_state WHERE id=1",[],|r|r.get(0)).unwrap();assert_eq!(old,actual);assert_eq!(db.query_row("PRAGMA user_version",[],|r|r.get::<_,i64>(0)).unwrap(),core::STORE_VERSION);
    }
